    (7, "用 while 求数字各位之和（多数字）。", "nums = [123, 45, 6]\ni = 0\nwhile i < len(nums):\n    n = nums[i]\n    total = 0\n    while n > 0:\n        total += n % 10\n        n //= 10\n    print(f\"{nums[i]}: {total}\")\n    i += 1", "填空嵌套位和。", "nums = [123, 45, 6]\ni = 0\nwhile i < len(nums):\n    n = nums[i]\n    total = 0\n    while n > 0:\n        total += n % 10\n        n //= 10\n    print(f\"{nums[i]}: {total}\")\n    i += 1"),
