    (9, "用 while 生成乘法口诀表。", "i = 1\nwhile i <= 5:\n    j = 1\n    row = []\n    while j <= i:\n        row.append(f\"{j}x{i}={i * j}\")\n        j += 1\n    print(\" \".join(row))\n    i += 1", "填空口诀表。", "i = 1\nwhile i <= 5:\n    j = 1\n    row = []\n    while j <= i:\n        row.append(f\"{j}x{i}={i * j}\")\n        j += 1\n    print(\" \".join(row))\n    i += 1"),
    (10, "用 while 判断回文数并输出过程。", "n = 1221\ntemp = n\nrev = 0\nwhile temp > 0:\n    rev = rev * 10 + temp % 10\n    temp //= 10\nif n == rev:\n    print(f\"{n} is palindrome\")\nelse:\n    print(f\"{n} is not\")", "填空回文判断。", "n = 1221\ntemp = n\nrev = 0\nwhile temp > 0:\n    rev = rev * 10 + temp % 10\n    temp //= 10\nif n == rev:\n    print(f\"{n} is palindrome\")\nelse:\n    print(f\"{n} is not\")"),
