    (12, "用 while 统计矩阵中正数个数。", "matrix = [[1, -2], [3, -4], [5, 6]]\ni = 0\ncount = 0\nwhile i < len(matrix):\n    j = 0\n    while j < len(matrix[i]):\n        if matrix[i][j] > 0:\n            count += 1\n        j += 1\n    i += 1\nprint(f\"Positive: {count}\")", "填空矩阵遍历。", "matrix = [[1, -2], [3, -4], [5, 6]]\ni = 0\ncount = 0\nwhile i < len(matrix):\n    j = 0\n    while j < len(matrix[i]):\n        if matrix[i][j] > 0:\n            count += 1\n        j += 1\n    i += 1\nprint(f\"Positive: {count}\")"),
    (13, "用 while 求数字反转并比较。", "nums = [123, 321]\ni = 0\nwhile i < len(nums):\n    n = nums[i]\n    rev = 0\n    while n > 0:\n        rev = rev * 10 + n % 10\n        n //= 10\n    print(f\"{nums[i]} -> {rev}\")\n    i += 1", "填空多数字反转。", "nums = [123, 321]\ni = 0\nwhile i < len(nums):\n    n = nums[i]\n    rev = 0\n    while n > 0:\n        rev = rev * 10 + n % 10\n        n //= 10\n    print(f\"{nums[i]} -> {rev}\")\n    i += 1"),
    (14, "用 while 输出 1 到 20 的完全平方数。", "n = 1\nsquares = []\nwhile n <= 20:\n    root = int(n ** 0.5)\n    if root * root == n:\n        squares.append(n)\n    n += 1\nprint(squares)", "填空平方判断。", "n = 1\nsquares = []\nwhile n <= 20:\n    root = int(n ** 0.5)\n    if root * root == n:\n        squares.append(n)\n    n += 1\nprint(squares)"),
    (15, "用 while 模拟存款利息增长。", "balance = 1000\nrate = 0.05\nyears = 0\nwhile balance < 1200:\n    balance *= 1 + rate\n    years += 1\nprint(f\"Years: {years}, Balance: {balance:.2f}\")", "填空复利循环。", "balance = 1000\nrate = 0.05\nyears = 0\nwhile balance < 1200:\n    balance *= 1 + rate\n    years += 1\nprint(f\"Years: {years}, Balance: {balance:.2f}\")"),
    (16, "用 while 求字符串中最长单词。", "text = \"the quick brown fox\"\nwords = text.split()\nlongest = \"\"\ni = 0\nwhile i < len(words):\n    if len(words[i]) > len(longest):\n        longest = words[i]\n    i += 1\nprint(f\"Longest: {longest}\")", "填空最长查找。", "text = \"the quick brown fox\"\nwords = text.split()\nlongest = \"\"\ni = 0\nwhile i < len(words):\n    if len(words[i]) > len(longest):\n        longest = words[i]\n    i += 1\nprint(f\"Longest: {longest}\")"),
