    (18, "用 while 求数组的最大子段和（简化）。", "nums = [1, -2, 3, 4, -1]\nmax_sum = nums[0]\ni = 0\nwhile i < len(nums):\n    cur = 0\n    j = i\n    while j < len(nums):\n        cur += nums[j]\n        if cur > max_sum:\n            max_sum = cur\n        j += 1\n    i += 1\nprint(max_sum)", "填空子段扫描。", "nums = [1, -2, 3, 4, -1]\nmax_sum = nums[0]\ni = 0\nwhile i < len(nums):\n    cur = 0\n    j = i\n    while j < len(nums):\n        cur += nums[j]\n        if cur > max_sum:\n            max_sum = cur\n        j += 1\n    i += 1\nprint(max_sum)"),
