    (22, "用 while 统计成绩分档。", "scores = [55, 72, 88, 91, 63]\ni = 0\ngrades = [\"A\", \"B\", \"C\", \"D\", \"F\"]\ncounts = [0, 0, 0, 0, 0]\nwhile i < len(scores):\n    s = scores[i]\n    if s >= 90:\n        counts[0] += 1\n    elif s >= 80:\n        counts[1] += 1\n    elif s >= 70:\n        counts[2] += 1\n    elif s >= 60:\n        counts[3] += 1\n    else:\n        counts[4] += 1\n    i += 1\nfor g, c in zip(grades, counts):\n    print(f\"{g}: {c}\")", "填空分档统计。", "scores = [55, 72, 88, 91, 63]\ni = 0\ngrades = [\"A\", \"B\", \"C\", \"D\", \"F\"]\ncounts = [0, 0, 0, 0, 0]\nwhile i < len(scores):\n    s = scores[i]\n    if s >= 90:\n        counts[0] += 1\n    elif s >= 80:\n        counts[1] += 1\n    elif s >= 70:\n        counts[2] += 1\n    elif s >= 60:\n        counts[3] += 1\n    else:\n        counts[4] += 1\n    i += 1\nfor g, c in zip(grades, counts):\n    print(f\"{g}: {c}\")"),
    (23, "用 while 求最小公倍数（多组）。", "pairs = [(3, 4), (6, 8), (5, 7)]\ni = 0\nwhile i < len(pairs):\n    a, b = pairs[i]\n    m = max(a, b)\n    while m % a != 0 or m % b != 0:\n        m += 1\n    print(f\"lcm({a}, {b}) = {m}\")\n    i += 1", "填空多组 lcm。", "pairs = [(3, 4), (6, 8), (5, 7)]\ni = 0\nwhile i < len(pairs):\n    a, b = pairs[i]\n    m = max(a, b)\n    while m % a != 0 or m % b != 0:\n        m += 1\n    print(f\"lcm({a}, {b}) = {m}\")\n    i += 1"),
    (24, "用 while 求数字的二进制中 1 的个数。", "n = 29\ncount = 0\nwhile n:\n    count += n & 1\n    n >>= 1\nprint(f\"Bits: {count}\")", "填空位计数。", "n = 29\ncount = 0\nwhile n:\n    count += n & 1\n    n >>= 1\nprint(f\"Bits: {count}\")"),
