    (27, "用 while 求两数之差最小配对。", "nums = [1, 5, 3, 9]\nnums.sort()\nmin_diff = nums[1] - nums[0]\ni = 1\nwhile i < len(nums) - 1:\n    diff = nums[i + 1] - nums[i]\n    if diff < min_diff:\n        min_diff = diff\n    i += 1\nprint(f\"Min diff: {min_diff}\")", "填空最小差。", "nums = [1, 5, 3, 9]\nnums.sort()\nmin_diff = nums[1] - nums[0]\ni = 1\nwhile i < len(nums) - 1:\n    diff = nums[i + 1] - nums[i]\n    if diff < min_diff:\n        min_diff = diff\n    i += 1\nprint(f\"Min diff: {min_diff}\")"),
