    (29, "用 while 求 3n+1 序列长度。", "n = 6\nsteps = 0\nwhile n != 1:\n    if n % 2 == 0:\n        n //= 2\n    else:\n        n = n * 3 + 1\n    steps += 1\nprint(f\"Steps: {steps}\")", "填空 3n+1。", "n = 6\nsteps = 0\nwhile n != 1:\n    if n % 2 == 0:\n        n //= 2\n    else:\n        n = n * 3 + 1\n    steps += 1\nprint(f\"Steps: {steps}\")"),
