    (15, "用 while 判断并输出素数对。", "def is_prime(n):\n    d = 2\n    while d * d <= n:\n        if n % d == 0:\n            return False\n        d += 1\n    return n > 1\nn = 2\nwhile n < 20:\n    if is_prime(n) and is_prime(n + 2):\n        print(n, n + 2)\n    n += 1", "填空孪生素数。", "def is_prime(n):\n    d = 2\n    while d * d <= n:\n        if n % d == 0:\n            return False\n        d += 1\n    return n > 1\nn = 2\nwhile n < 20:\n    if is_prime(n) and is_prime(n + 2):\n        print(n, n + 2)\n    n += 1"),
