    (18, "用 while 生成螺旋矩阵。", "n = 3\nmatrix = [[0] * n for _ in range(n)]\nnum = 1\ntop, bottom, left, right = 0, n - 1, 0, n - 1\nwhile top <= bottom and left <= right:\n    j = left\n    while j <= right:\n        matrix[top][j] = num\n        num += 1\n        j += 1\n    top += 1\n    i = top\n    while i <= bottom:\n        matrix[i][right] = num\n        num += 1\n        i += 1\n    right -= 1\n    j = right\n    while j >= left:\n        matrix[bottom][j] = num\n        num += 1\n        j -= 1\n    bottom -= 1\n    i = bottom\n    while i >= top:\n        matrix[i][left] = num\n        num += 1\n        i -= 1\n    left += 1\nfor row in matrix:\n    print(row)", "填空螺旋矩阵。", "n = 3\nmatrix = [[0] * n for _ in range(n)]\nnum = 1\ntop, bottom, left, right = 0, n - 1, 0, n - 1\nwhile top <= bottom and left <= right:\n    j = left\n    while j <= right:\n        matrix[top][j] = num\n        num += 1\n        j += 1\n    top += 1\n    i = top\n    while i <= bottom:\n        matrix[i][right] = num\n        num += 1\n        i += 1\n    right -= 1\n    j = right\n    while j >= left:\n        matrix[bottom][j] = num\n        num += 1\n        j -= 1\n    bottom -= 1\n    i = bottom\n    while i >= top:\n        matrix[i][left] = num\n        num += 1\n        i -= 1\n    left += 1\nfor row in matrix:\n    print(row)"),
