    (20, "用 while 模拟二进制加法。", "def bin_add(a, b):\n    result = \"\"\n    carry = 0\n    i = len(a) - 1\n    j = len(b) - 1\n    while i >= 0 or j >= 0 or carry:\n        x = int(a[i]) if i >= 0 else 0\n        y = int(b[j]) if j >= 0 else 0\n        total = x + y + carry\n        result = str(total % 2) + result\n        carry = total // 2\n        i -= 1\n        j -= 1\n    return result\nprint(bin_add(\"101\", \"11\"))", "填空二进制加法。", "def bin_add(a, b):\n    result = \"\"\n    carry = 0\n    i = len(a) - 1\n    j = len(b) - 1\n    while i >= 0 or j >= 0 or carry:\n        x = int(a[i]) if i >= 0 else 0\n        y = int(b[j]) if j >= 0 else 0\n        total = x + y + carry\n        result = str(total % 2) + result\n        carry = total // 2\n        i -= 1\n        j -= 1\n    return result\nprint(bin_add(\"101\", \"11\"))"),
